import csv,collections,pathlib
loci=list(csv.DictReader(open('outputs/stage3_provisional_locus_triage.csv')));table=list(csv.DictReader(open('outputs/stage3_initial_variant_gene_table.csv')));regs=list(csv.DictReader(open('outputs/stage3_ensembl_regulatory_10kb.csv')));abcpath=pathlib.Path('outputs/stage3_abc_candidate_regulatory_links.csv');abc=list(csv.DictReader(abcpath.open())) if abcpath.exists() else [];p=pathlib.Path('outputs/stage3_abc_ld_proxy_regulatory_links.csv');proxyabc=list(csv.DictReader(p.open())) if p.exists() else [];out=[]
for loc in loci:
 markers=loc['markers'].split(';');r=[x for x in table if x['Variant'] in markers];qs=[x for x in r if 'GTEx v10 precomputed' in x['eQTL'] or 'GTEx v10 precomputed' in x['sQTL']];genes=sorted({x['Candidate gene'] for x in qs if x['Candidate gene']});tissues=sorted({x['Tissue'] for x in qs});computed=sorted({x['Colocalization'] for x in r if x['Colocalization'].startswith('Exploratory')});fine=sorted({x['Molecular fine mapping'] for x in r if x['Molecular fine mapping'] not in ('not yet evaluated','')});features={x['regulatory_feature_id'] for x in regs if x['variant'] in markers}
 out.append({'triage_rank':loc['triage_rank'],'locus_GRCh37_assumed':loc['locus'],'markers':loc['markers'],'positional_gene_labels':loc['positional_gene_labels'],'exact_marker_gtex_genes':';'.join(genes),'gtex_gene_count':len(genes),'gtex_tissues':';'.join(tissues),'gtex_gene_tissue_rows':len(qs),'ensembl_features_within_10kb':len(features),'abc_predicted_target_labels':';'.join(sorted({x['TargetGene'] for x in abc if x['candidate'] in markers})),'abc_prediction_rows':sum(x['candidate'] in markers for x in abc),'abc_ld_proxy_predicted_target_labels':';'.join(sorted({x['TargetGene'] for x in proxyabc if x['candidate'] in markers})),'abc_ld_proxy_prediction_rows':sum(x['candidate'] in markers for x in proxyabc),'colocalization_status':('exploratory comparisons present; inspect source reports' if computed else 'not yet evaluated'),'fine_mapping_status':('fine-mapping note present for at least one gene or molecular phenotype; inspect source reports' if fine else 'not yet evaluated'),'warning':'candidate-selected marker summary, not an independent locus, causal gene, negative QTL screen or validated shared-risk test'})
with open('outputs/stage3_region_evidence_inventory.csv','w',newline='') as f:w=csv.DictWriter(f,fieldnames=out[0]);w.writeheader();w.writerows(out)
print('regions',len(out),'with gtex genes',sum(int(x['gtex_gene_count'])>0 for x in out),'with exploratory coloc',sum(x['colocalization_status'].startswith('exploratory') for x in out),'fine mapping',sum(x['fine_mapping_status'].startswith('fine-mapping') for x in out))
